INSERT INTO public.products (sku, collection_id, super_category, title, title_bn, slug, price_bdt, price_review, price_confidence, description_bn, description_en, selling_unit, selling_unit_bn, caution_en, caution_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, stock_count, stock_verified, accent_color, is_featured) VALUES ('CAT-001', '01', 'Fashion', 'Magenta Plum Printed Three Piece', 'ম্যাজেন্টা ও প্লাম প্রিন্টেড থ্রি-পিস', 'magenta-plum-printed-three-piece', 2350, true, 'suggested', 'ম্যাজেন্টা ও প্লামের আকর্ষণীয় বৈপরীত্যে সাজানো এই থ্রি-পিসে আছে সাদা-গোলাপি ফুল, পেইসলি মোটিফ ও ডেকোরেটিভ বর্ডার। উজ্জ্বল ফুশিয়া সলিড কাপড় এবং ট্যাসেলসহ প্রিন্টেড ওড়না পুরো সেটে যোগ করে প্রাণবন্ত ফিনিশ।', 'Rich magenta and plum printed three-piece featuring white-pink florals, paisley motifs, solid fuchsia bottom fabric, and a tasseled printed dupatta.', '3-Piece Set', 'থ্রি-পিস সেট (আনস্টিচড)', 'Seller-labeled collection. Reference price ৳2,350 — confirm size & availability with seller.', 'বিক্রেতা-লেবেলকৃত কালেকশন (আড়ং অ্যাফিলিয়েশন যাচাইকৃত নয়)। রেফারেন্স মূল্য ৳2,350 — অর্ডারের আগে স্টক ও সাইজ নিশ্চিত করুন।', 'প্লাম বেসে ফ্লোরাল-পেইসলি প্রিন্ট ও বর্ডার', 'উজ্জ্বল ফুশিয়া/পিংক সলিড কাপড়', 'ম্যাজেন্টা-প্লাম প্রিন্ট ও ট্যাসেল', 'Artisanal Handcraft', 'আলাদা হাতার কাপড়সহ আনস্টিচড', 0, false, '#8E3B66', true) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn, description_en = EXCLUDED.description_en, selling_unit = EXCLUDED.selling_unit, selling_unit_bn = EXCLUDED.selling_unit_bn, caution_en = EXCLUDED.caution_en, caution_bn = EXCLUDED.caution_bn, super_category = EXCLUDED.super_category;
INSERT INTO public.products (sku, collection_id, super_category, title, title_bn, slug, price_bdt, price_review, price_confidence, description_bn, description_en, selling_unit, selling_unit_bn, caution_en, caution_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, stock_count, stock_verified, accent_color, is_featured) VALUES ('CAT-002', '02', 'Fashion', 'Emerald Teal Batik', 'এমেরাল্ড টিল বাটিক থ্রি-পিস', 'emerald-teal-batik', 2150, true, 'suggested', 'কালো ও আইভরি রঙের অ্যাবস্ট্রাক্ট বাটিক-অনুপ্রাণিত নকশায় একটি স্বতন্ত্র লুক। টিল-সবুজ টাই-ডাই ঘরানার ওড়নার রাস্ট বর্ডার এবং টেরাকোটা রঙের সলিড কাপড় যোগ করেছে সাহসী, মার্জিত কনট্রাস্ট।', 'Charcoal and ivory batik-inspired floral geometric print paired with terracotta solid fabric and a teal-green rust-bordered dupatta.', '3-Piece Set', 'থ্রি-পিস সেট', 'Catalog reference price ৳2,150 — confirm size & availability on Messenger.', 'ক্যাটালগ রেফারেন্স মূল্য ৳2,150 — অর্ডারের আগে সাইজ ও স্টক নিশ্চিত করুন।', 'কালো/চারকোল বেসে আইভরি ফ্লোরাল ও জ্যামিতিক প্রিন্ট', 'টেরাকোটা/রাস্ট সলিড কাপড়', 'টিল-সবুজ স্ট্রাইপ ও রাস্ট বর্ডার', 'Artisanal Handcraft', 'আনস্টিচড বাটিক সেট', 0, false, '#1F6E63', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn, description_en = EXCLUDED.description_en, selling_unit = EXCLUDED.selling_unit, selling_unit_bn = EXCLUDED.selling_unit_bn, caution_en = EXCLUDED.caution_en, caution_bn = EXCLUDED.caution_bn, super_category = EXCLUDED.super_category;
INSERT INTO public.products (sku, collection_id, super_category, title, title_bn, slug, price_bdt, price_review, price_confidence, description_bn, description_en, selling_unit, selling_unit_bn, caution_en, caution_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, stock_count, stock_verified, accent_color, is_featured) VALUES ('CAT-003', '02', 'Fashion', 'Dusty Mauve Floral Batik', 'ডাস্টি মভ ফ্লোরাল বাটিক থ্রি-পিস', 'dusty-mauve-floral-batik', 2050, true, 'suggested', 'ডাস্টি মভের কোমল রঙে অফ-হোয়াইট ফুল এবং বড় বৃত্তাকার বাটিক মোটিফের পরিমিত সৌন্দর্য। একই টোনের সলিড কাপড় ও সূক্ষ্ম ফ্লোরাল প্রিন্টের ট্যাসেলযুক্ত ওড়নায় তৈরি হয়েছে সহজ, রুচিশীল থ্রি-পিস কম্বিনেশন।', 'Soft dusty mauve ensemble with off-white florals, circular batik motifs, matching solid bottom fabric, and a tasseled floral dupatta.', '3-Piece Set', 'থ্রি-পিস সেট', 'Catalog reference price ৳2,050 — confirm with seller.', 'ক্যাটালগ রেফারেন্স মূল্য ৳2,050 — অর্ডারের আগে নিশ্চিত করুন।', 'ডাস্টি মভে সাদা ফুল ও গোলাকার বাটিক মোটিফ', 'ম্যাচিং ডাস্টি মভ সলিড কাপড়', 'মভ ফ্লোরাল প্রিন্ট, সূক্ষ্ম টেক্সচার ও ট্যাসেল', 'Artisanal Handcraft', 'আনস্টিচড বাটিক সেট', 0, false, '#A87C8F', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn, description_en = EXCLUDED.description_en, selling_unit = EXCLUDED.selling_unit, selling_unit_bn = EXCLUDED.selling_unit_bn, caution_en = EXCLUDED.caution_en, caution_bn = EXCLUDED.caution_bn, super_category = EXCLUDED.super_category;
INSERT INTO public.products (sku, collection_id, super_category, title, title_bn, slug, price_bdt, price_review, price_confidence, description_bn, description_en, selling_unit, selling_unit_bn, caution_en, caution_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, stock_count, stock_verified, accent_color, is_featured) VALUES ('CAT-004', '03', 'Fashion', 'Forest Elegance', 'ফরেস্ট এলিগ্যান্স', 'forest-elegance', 1850, true, 'suggested', 'মাটির রঙের উষ্ণতা ও ফরেস্ট গ্রিনের গভীরতা মিলেছে বোটানিক্যাল বাটিক-অনুপ্রাণিত নকশায়। ড্রেস ম্যাটেরিয়ালের সঙ্গে বাদামি সলিড কাপড় ও সবুজ গ্রেডিয়েন্ট ওড়নার পাতার ছাপ এবং ট্যাসেল পুরো লুকে আনে প্রাকৃতিক আবহ।', 'Earthy brown and forest green botanical print dress material with solid brown bottom and cream-leaf green gradient dupatta.', 'Dress Material', 'ড্রেস ম্যাটেরিয়াল সেট', 'Reference price ৳1,850 — dress materials shown.', 'রেফারেন্স মূল্য ৳1,850 — আনস্টিচড ড্রেস ম্যাটেরিয়াল।', 'আর্থি ব্রাউন ও ফরেস্ট গ্রিন বোটানিক্যাল প্রিন্ট', 'সলিড ব্রাউন কাপড়', 'সবুজ গ্রেডিয়েন্ট ওড়না, ক্রিম বোটানিক্যাল ছাপ', 'Artisanal Handcraft', 'ড্রেস ম্যাটেরিয়াল', 0, false, '#3E5E3A', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn, description_en = EXCLUDED.description_en, selling_unit = EXCLUDED.selling_unit, selling_unit_bn = EXCLUDED.selling_unit_bn, caution_en = EXCLUDED.caution_en, caution_bn = EXCLUDED.caution_bn, super_category = EXCLUDED.super_category;
INSERT INTO public.products (sku, collection_id, super_category, title, title_bn, slug, price_bdt, price_review, price_confidence, description_bn, description_en, selling_unit, selling_unit_bn, caution_en, caution_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, stock_count, stock_verified, accent_color, is_featured) VALUES ('CAT-005', '03', 'Fashion', 'Fuchsia Noir', 'ফুশিয়া নোয়ার', 'fuchsia-noir', 1700, true, 'suggested', 'তীক্ষ্ণ ফুশিয়া-পিংক ও চারকোলের ড্রামাটিক কনট্রাস্টে নজরকাড়া বাটিক থ্রি-পিস ম্যাটেরিয়াল। কামিজের ওপর গোলাপি ও সাদা ফুলেল ছাপ, সঙ্গে সলিড ফুশিয়া কাপড় এবং গাঢ় থেকে উজ্জ্বল রঙে পরিবর্তিত ওড়না।', 'Dramatic fuchsia-pink and charcoal batik-style dress material with floral motifs, solid fuchsia bottom, and gradient dupatta.', 'Dress Material', 'ড্রেস ম্যাটেরিয়াল সেট', 'Reference price ৳1,700 — confirm stock on inquiry.', 'রেফারেন্স মূল্য ৳1,700 — অর্ডারের আগে স্টক নিশ্চিত করুন।', 'চারকোল/কালো বেসে ফুশিয়া ও সাদা ফ্লোরাল প্রিন্ট', 'উজ্জ্বল ফুশিয়া সলিড কাপড়', 'ফুশিয়া-চারকোল গ্রেডিয়েন্ট ও ফুলের মোটিফ', 'Artisanal Handcraft', 'ড্রেস ম্যাটেরিয়াল', 0, false, '#B0326E', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn, description_en = EXCLUDED.description_en, selling_unit = EXCLUDED.selling_unit, selling_unit_bn = EXCLUDED.selling_unit_bn, caution_en = EXCLUDED.caution_en, caution_bn = EXCLUDED.caution_bn, super_category = EXCLUDED.super_category;
INSERT INTO public.products (sku, collection_id, super_category, title, title_bn, slug, price_bdt, price_review, price_confidence, description_bn, description_en, selling_unit, selling_unit_bn, caution_en, caution_bn, kameez_bn, salwar_bn, dupatta_bn, fabric_claim, stitching, stock_count, stock_verified, accent_color, is_featured) VALUES ('CAT-006', '03', 'Fashion', 'Mustard Noir', 'মাস্টার্ড নোয়ার', 'mustard-noir', 1650, true, 'suggested', 'উজ্জ্বল মাস্টার্ড ও গাঢ় চারকোলের দুই-টোন প্যালেটে ক্লাসিক বাটিক ঘরানার নকশা। ছোট বোটানিক্যাল রিপিট প্রিন্টের সঙ্গে সলিড হলুদ কাপড় ও গ্রেডিয়েন্ট ওড়না।', 'Two-tone mustard yellow and deep charcoal botanical repeat dress material with solid mustard bottom and gradient dupatta.', 'Dress Material', 'ড্রেস ম্যাটেরিয়াল সেট', 'Reference price ৳1,650 — confirm with seller.', 'রেফারেন্স মূল্য ৳1,650 — অর্ডারের আগে নিশ্চিত করুন।', 'চারকোল বেসে মাস্টার্ড বোটানিক্যাল রিপিট', 'সলিড মাস্টার্ড হলুদ কাপড়', 'হলুদ-চারকোল গ্রেডিয়েন্ট ওড়না', 'Artisanal Handcraft', 'ড্রেস ম্যাটেরিয়াল', 0, false, '#C0912F', false) ON CONFLICT (sku) DO UPDATE SET title = EXCLUDED.title, title_bn = EXCLUDED.title_bn, description_bn = EXCLUDED.description_bn, description_en = EXCLUDED.description_en, selling_unit = EXCLUDED.selling_unit, selling_unit_bn = EXCLUDED.selling_unit_bn, caution_en = EXCLUDED.caution_en, caution_bn = EXCLUDED.caution_bn, super_category = EXCLUDED.super_category;
